CREATE TABLE employee_custody_settlements (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,custody_id BIGINT UNSIGNED NOT NULL,settlement_type VARCHAR(20) NOT NULL,settlement_date DATE NOT NULL,description VARCHAR(500) NOT NULL,cost_code_id BIGINT UNSIGNED NULL,amount DECIMAL(18,2) NOT NULL,project_id BIGINT UNSIGNED NULL,return_account_id BIGINT UNSIGNED NULL,reference VARCHAR(190) NULL,sort_order INT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,journal_entry_id BIGINT UNSIGNED NULL,project_actual_cost_id BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_custody_settlement_journal(journal_entry_id),UNIQUE KEY uq_custody_settlement_cost(project_actual_cost_id),KEY idx_custody_settlements_order(custody_id,sort_order,id),CONSTRAINT fk_custody_settlements_custody FOREIGN KEY(custody_id) REFERENCES employee_custodies(id) ON DELETE RESTRICT,CONSTRAINT fk_custody_settlements_cost_code FOREIGN KEY(cost_code_id) REFERENCES cost_codes(id) ON DELETE RESTRICT,CONSTRAINT fk_custody_settlements_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_custody_settlements_return_account FOREIGN KEY(return_account_id) REFERENCES accounts(id) ON DELETE RESTRICT,CONSTRAINT fk_custody_settlements_created FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_custody_settlements_journal FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id) ON DELETE RESTRICT,CONSTRAINT fk_custody_settlements_actual_cost FOREIGN KEY(project_actual_cost_id) REFERENCES project_actual_costs(id) ON DELETE RESTRICT,CONSTRAINT chk_custody_settlements_type CHECK(settlement_type IN('expense','cash_return')),CONSTRAINT chk_custody_settlements_amount CHECK(amount>0),CONSTRAINT chk_custody_settlements_sort CHECK(sort_order>0),CONSTRAINT chk_custody_settlements_effect CHECK((settlement_type='expense' AND project_id IS NOT NULL AND cost_code_id IS NOT NULL AND return_account_id IS NULL) OR(settlement_type='cash_return' AND project_id IS NULL AND cost_code_id IS NULL AND return_account_id IS NOT NULL AND project_actual_cost_id IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
